import type { ExerciseQuestion } from "../types";

export const TENSE_QUESTIONS: ExerciseQuestion[] = [
  { id: "t001", question: "She _____ to work by bus every day.", options: ["travel", "travels", "is travelling", "travelled"], correctIndex: 1, explanation: "Dùng Present Simple cho thói quen. Chủ ngữ ngôi 3 số ít (she/he/it) thêm -s vào động từ." },
  { id: "t002", question: "Water _____ at 100°C at sea level.", options: ["boil", "boils", "is boiling", "boiled"], correctIndex: 1, explanation: "Dùng Present Simple cho sự thật khoa học và chân lý." },
  { id: "t003", question: "They _____ football at the park right now.", options: ["play", "plays", "are playing", "played"], correctIndex: 2, explanation: "Dùng Present Continuous (am/is/are + V-ing) cho hành động đang xảy ra ngay bây giờ." },
  { id: "t004", question: "Look! It _____ outside.", options: ["snow", "snows", "is snowing", "snowed"], correctIndex: 2, explanation: "Dùng Present Continuous khi dùng 'Look!' để chỉ hành động đang diễn ra trước mắt." },
  { id: "t005", question: "She _____ to Paris for a conference next Monday. (arranged)", options: ["flies", "flew", "will fly", "is flying"], correctIndex: 3, explanation: "Dùng Present Continuous cho kế hoạch đã sắp xếp sẵn trong tương lai." },
  { id: "t006", question: "Columbus _____ America in 1492.", options: ["discovers", "has discovered", "discovered", "is discovering"], correctIndex: 2, explanation: "Dùng Past Simple cho sự kiện lịch sử đã hoàn thành tại một thời điểm cụ thể trong quá khứ." },
  { id: "t007", question: "I _____ my keys yesterday.", options: ["lose", "am losing", "have lost", "lost"], correctIndex: 3, explanation: "Dùng Past Simple với 'yesterday' vì thời điểm cụ thể trong quá khứ." },
  { id: "t008", question: "We _____ dinner when the phone rang.", options: ["had", "have", "were having", "are having"], correctIndex: 2, explanation: "Dùng Past Continuous (was/were + V-ing) cho hành động đang diễn ra khi bị gián đoạn bởi sự kiện khác." },
  { id: "t009", question: "She _____ a bath while her brother was watching TV.", options: ["takes", "took", "was taking", "has taken"], correctIndex: 2, explanation: "Hai hành động song song trong quá khứ → đều dùng Past Continuous." },
  { id: "t010", question: "I _____ never been to Japan.", options: ["have", "had", "am", "was"], correctIndex: 0, explanation: "Present Perfect (have/has + V3) cho kinh nghiệm sống chưa từng trải qua." },
  { id: "t011", question: "She _____ for this company since 2018.", options: ["works", "worked", "has worked", "is working"], correctIndex: 2, explanation: "Dùng Present Perfect với 'since' (kể từ khi) cho hành động bắt đầu trong quá khứ và vẫn tiếp tục đến hiện tại." },
  { id: "t012", question: "Have you _____ the new restaurant on Main Street?", options: ["try", "tried", "trying", "tries"], correctIndex: 1, explanation: "Have/Has + V3 (past participle). 'Try' → 'tried'." },
  { id: "t013", question: "He has just _____ from a long trip.", options: ["return", "returned", "returning", "returns"], correctIndex: 1, explanation: "Present Perfect + 'just' diễn tả hành động vừa mới hoàn thành." },
  { id: "t014", question: "We have not _____ the report yet.", options: ["finish", "finished", "finishing", "finishes"], correctIndex: 1, explanation: "Have + not + V3 cho phủ định Present Perfect. 'Yet' thường dùng ở cuối câu phủ định/câu hỏi." },
  { id: "t015", question: "By the time we arrived, the show _____.", options: ["starts", "started", "had started", "has started"], correctIndex: 2, explanation: "Dùng Past Perfect (had + V3) cho hành động hoàn thành trước một hành động khác trong quá khứ." },
  { id: "t016", question: "She was exhausted because she _____ all night.", options: ["work", "worked", "was working", "had been working"], correctIndex: 3, explanation: "Past Perfect Continuous (had been + V-ing) diễn tả hành động liên tục trong quá khứ dẫn đến kết quả tại một thời điểm quá khứ." },
  { id: "t017", question: "'There's someone at the door.' 'I _____ get it.'", options: ["am going to", "going to", "'ll", "would"], correctIndex: 2, explanation: "Dùng 'will' cho quyết định tức thì ngay tại thời điểm nói." },
  { id: "t018", question: "Look at those dark clouds — it _____ rain.", options: ["will", "is going to", "shall", "would"], correctIndex: 1, explanation: "Dùng 'be going to' khi có bằng chứng cụ thể về điều sắp xảy ra." },
  { id: "t019", question: "She _____ study abroad next year. (She's already applied)", options: ["will", "is going to", "would", "shall"], correctIndex: 1, explanation: "Dùng 'be going to' cho kế hoạch đã được lên sẵn trước khi nói." },
  { id: "t020", question: "The train _____ at 6:15 according to the timetable.", options: ["will leave", "is going to leave", "leaves", "left"], correctIndex: 2, explanation: "Dùng Present Simple cho lịch trình cố định (thời khóa biểu, chuyến tàu/xe)." },
  { id: "t021", question: "By next summer, she _____ her degree.", options: ["finishes", "will finish", "will have finished", "is finishing"], correctIndex: 2, explanation: "Dùng Future Perfect (will have + V3) cho hành động sẽ hoàn thành trước một thời điểm trong tương lai." },
  { id: "t022", question: "This time tomorrow, I _____ on a plane.", options: ["fly", "will fly", "will be flying", "am flying"], correctIndex: 2, explanation: "Dùng Future Continuous (will be + V-ing) cho hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai." },
  { id: "t023", question: "I _____ to learn piano ever since I was a child.", options: ["want", "wanted", "have wanted", "am wanting"], correctIndex: 2, explanation: "Dùng Present Perfect cho trạng thái/mong muốn bắt đầu từ quá khứ và vẫn còn đến hiện tại." },
  { id: "t024", question: "He _____ for three hours when the storm finally stopped.", options: ["drove", "was driving", "had been driving", "has been driving"], correctIndex: 2, explanation: "Dùng Past Perfect Continuous (had been + V-ing) cho hành động liên tục trước một thời điểm/sự kiện khác trong quá khứ." },
  { id: "t025", question: "I _____ here since 8 AM and nobody has called me.", options: ["sit", "sat", "am sitting", "have been sitting"], correctIndex: 3, explanation: "Dùng Present Perfect Continuous (have been + V-ing) cho hành động bắt đầu trong quá khứ và vẫn tiếp tục đến hiện tại, nhấn mạnh tính liên tục." },
  { id: "t026", question: "She _____ always _____ her pen. (annoying habit)", options: ["is/losing", "has/lost", "does/lose", "was/losing"], correctIndex: 0, explanation: "Dùng Present Continuous + always để diễn tả thói quen gây khó chịu." },
  { id: "t027", question: "He told me he _____ be there on time.", options: ["will", "would", "is", "was"], correctIndex: 1, explanation: "Trong lời tường thuật (reported speech), 'will' chuyển thành 'would'." },
  { id: "t028", question: "_____ you enjoy the concert last night?", options: ["Do", "Did", "Have", "Were"], correctIndex: 1, explanation: "Câu hỏi với Past Simple dùng 'Did'. 'Last night' là thời điểm cụ thể trong quá khứ." },
  { id: "t029", question: "I realized I _____ my wallet at home.", options: ["leave", "left", "had left", "have left"], correctIndex: 2, explanation: "Dùng Past Perfect vì hành động 'để quên' xảy ra trước hành động 'nhận ra'." },
  { id: "t030", question: "This is the most exciting film I _____ ever _____.", options: ["have/seen", "had/seen", "am/seeing", "was/seeing"], correctIndex: 0, explanation: "Sau cấu trúc 'the most...I have ever', dùng Present Perfect." },
  { id: "t031", question: "She _____ three cups of coffee before the meeting started.", options: ["drinks", "drank", "had drunk", "has drunk"], correctIndex: 2, explanation: "Dùng Past Perfect vì hành động uống cà phê xảy ra trước khi cuộc họp bắt đầu." },
  { id: "t032", question: "_____ she live near here?", options: ["Do", "Does", "Is", "Has"], correctIndex: 1, explanation: "Câu hỏi Present Simple với ngôi 3 số ít (she) dùng 'Does'." },
  { id: "t033", question: "They _____ arrived at the airport when they realized they forgot their passports.", options: ["just", "had just", "have just", "just have"], correctIndex: 1, explanation: "Dùng Past Perfect + 'just' cho hành động vừa hoàn thành trước một sự kiện khác trong quá khứ." },
  { id: "t034", question: "I _____ call you the moment I arrive.", options: ["am going to", "am", "'ll", "would"], correctIndex: 2, explanation: "Dùng 'will' cho lời hứa hoặc cam kết tự phát." },
  { id: "t035", question: "What _____ you _____ at 8pm last Saturday?", options: ["do/do", "did/do", "were/doing", "have/done"], correctIndex: 2, explanation: "Hỏi về hành động đang diễn ra tại một thời điểm cụ thể trong quá khứ → Past Continuous." },
  { id: "t036", question: "The museum _____ its 100th anniversary next year.", options: ["celebrates", "is celebrating", "will be celebrating", "celebrated"], correctIndex: 1, explanation: "Present Continuous cho kế hoạch/sự kiện đã được lên lịch trong tương lai gần." },
  { id: "t037", question: "After she _____ the letter, she felt much better.", options: ["sent", "has sent", "had sent", "was sending"], correctIndex: 2, explanation: "Dùng Past Perfect sau 'after' khi nói về hành động hoàn thành trước hành động còn lại." },
  { id: "t038", question: "Don't worry — I _____ help you move this weekend.", options: ["am going to", "'ll", "would", "am"], correctIndex: 1, explanation: "Dùng 'will' để đưa ra lời đề nghị hoặc lời hứa ngay tại thời điểm nói." },
  { id: "t039", question: "She _____ in this city for twenty years before she moved abroad.", options: ["lives", "lived", "has lived", "had lived"], correctIndex: 3, explanation: "Dùng Past Perfect (had lived) cho hành động diễn ra liên tục trong quá khứ trước một thời điểm quá khứ khác." },
  { id: "t040", question: "I'm exhausted — I _____ since 6 AM.", options: ["work", "worked", "am working", "have been working"], correctIndex: 3, explanation: "Present Perfect Continuous diễn tả hành động liên tục từ quá khứ đến hiện tại, giải thích cho trạng thái hiện tại." },
  { id: "t041", question: "The earth _____ around the sun once every 365 days.", options: ["travels", "travel", "is travelling", "has travelled"], correctIndex: 0, explanation: "Sự thật khoa học/chân lý → Present Simple. Ngôi 3 số ít thêm -s." },
  { id: "t042", question: "She _____ never _____ sushi until she visited Japan.", options: ["had/tried", "has/tried", "was/trying", "did/try"], correctIndex: 0, explanation: "Dùng Past Perfect + never cho kinh nghiệm chưa có cho đến một thời điểm trong quá khứ." },
  { id: "t043", question: "By 10 PM tonight, I _____ this book.", options: ["finish", "will finish", "will have finished", "am finishing"], correctIndex: 2, explanation: "Dùng Future Perfect (will have + V3) cho hành động sẽ hoàn thành trước một thời điểm cụ thể trong tương lai." },
  { id: "t044", question: "The kids _____ TV when their parents came home.", options: ["watch", "watched", "were watching", "have watched"], correctIndex: 2, explanation: "Past Continuous cho hành động đang diễn ra khi một hành động khác xảy ra (cha mẹ về)." },
  { id: "t045", question: "I _____ German for three years but I still can't speak it well.", options: ["learn", "am learning", "have been learning", "learned"], correctIndex: 2, explanation: "Present Perfect Continuous nhấn mạnh quá trình liên tục từ quá khứ đến hiện tại." },
  { id: "t046", question: "When I _____ at the office, everyone had already left.", options: ["arrive", "arrived", "had arrived", "have arrived"], correctIndex: 1, explanation: "'When' + Past Simple → hành động xảy ra vào một thời điểm cụ thể. Past Perfect dùng cho hành động xảy ra trước đó." },
  { id: "t047", question: "She _____ the piano since she was five years old.", options: ["plays", "played", "has played", "had played"], correctIndex: 2, explanation: "Dùng Present Perfect với 'since' → hành động bắt đầu trong quá khứ và tiếp tục đến hiện tại." },
  { id: "t048", question: "He _____ not eaten anything all day.", options: ["does", "did", "has", "is"], correctIndex: 2, explanation: "Present Perfect phủ định: has/have + not + V3. 'All day' = khoảng thời gian từ đầu ngày đến hiện tại." },
  { id: "t049", question: "She said she _____ study harder from then on.", options: ["will", "would", "is going to", "shall"], correctIndex: 1, explanation: "Reported speech: 'will' → 'would' khi chuyển sang lời tường thuật." },
  { id: "t050", question: "I _____ a strange dream last night.", options: ["have", "had", "am having", "have had"], correctIndex: 1, explanation: "Past Simple với 'last night' (thời điểm cụ thể đã qua)." },
  { id: "t051", question: "The sun _____ in the west.", options: ["set", "sets", "is setting", "has set"], correctIndex: 1, explanation: "Sự thật tự nhiên/chân lý → Present Simple. Ngôi 3 số ít (the sun) thêm -s." },
  { id: "t052", question: "Dogs _____ meat.", options: ["eat", "eats", "are eating", "have eaten"], correctIndex: 0, explanation: "Sự thật chung/thói quen chung → Present Simple. 'Dogs' = số nhiều, không thêm -s." },
  { id: "t053", question: "My father _____ to bed at 10 PM every night.", options: ["go", "goes", "is going", "has gone"], correctIndex: 1, explanation: "Thói quen hàng ngày → Present Simple. 'My father' = ngôi 3 số ít → 'goes'." },
  { id: "t054", question: "I _____ understand this problem. (state verb)", options: ["am not", "don't", "haven't", "wasn't"], correctIndex: 1, explanation: "'Understand' là state verb (động từ trạng thái), không dùng dạng -ing. Phủ định Present Simple: don't." },
  { id: "t055", question: "She _____ like coffee — she prefers tea.", options: ["doesn't", "isn't", "hasn't", "wasn't"], correctIndex: 0, explanation: "'Like' là state verb. Phủ định Present Simple ngôi 3 số ít: doesn't + V nguyên thể." },
  { id: "t056", question: "He _____ know the answer right now.", options: ["isn't", "doesn't", "hasn't", "wasn't"], correctIndex: 1, explanation: "'Know' là state verb, không dùng continuous. Dùng Present Simple phủ định: doesn't know." },
  { id: "t057", question: "I _____ the new Taylor Swift album right now — it's great!", options: ["love", "am loving", "have loved", "loved"], correctIndex: 0, explanation: "'Love' là state verb, không dùng dạng continuous. Dùng Present Simple." },
  { id: "t058", question: "She _____ her sister very much.", options: ["resembles", "is resembling", "has resembled", "resembled"], correctIndex: 0, explanation: "'Resemble' là state verb chỉ trạng thái, dùng Present Simple, không dùng continuous." },
  { id: "t059", question: "They _____ to leave tomorrow morning. (temporary arrangement)", options: ["plan", "planned", "are planning", "have planned"], correctIndex: 2, explanation: "Present Continuous cho kế hoạch/sắp xếp cụ thể trong tương lai gần." },
  { id: "t060", question: "He _____ always _____ his homework at the last minute. (irritating habit)", options: ["is/doing", "has/done", "does/do", "will/do"], correctIndex: 0, explanation: "Present Continuous + always cho thói quen gây khó chịu (always + V-ing = irritating habit)." },
  { id: "t061", question: "I _____ a lot of coffee lately — I need to cut down.", options: ["drink", "drank", "have been drinking", "am drinking"], correctIndex: 2, explanation: "Present Perfect Continuous với 'lately' diễn tả hành động lặp lại gần đây, ảnh hưởng đến hiện tại." },
  { id: "t062", question: "She _____ to music while she was doing her homework.", options: ["listens", "listened", "was listening", "has listened"], correctIndex: 2, explanation: "Hai hành động song song trong quá khứ: was listening (đang nghe) + was doing (đang làm)." },
  { id: "t063", question: "The children _____ outside when it started to rain.", options: ["play", "played", "were playing", "have played"], correctIndex: 2, explanation: "Past Continuous (were playing) cho hành động đang diễn ra khi bị gián đoạn (it started to rain)." },
  { id: "t064", question: "He _____ his arm when he fell off his bike.", options: ["breaks", "broke", "was breaking", "has broken"], correctIndex: 1, explanation: "Past Simple cho hai sự kiện xảy ra nhanh chóng liên tiếp trong quá khứ: fell → broke." },
  { id: "t065", question: "I _____ that film three times already.", options: ["see", "saw", "have seen", "am seeing"], correctIndex: 2, explanation: "Present Perfect với 'already' và số lần đã làm → nhấn mạnh kinh nghiệm." },
  { id: "t066", question: "Has she _____ her homework yet?", options: ["do", "did", "done", "doing"], correctIndex: 2, explanation: "Present Perfect câu hỏi: Has + S + V3. 'Do' → past participle = 'done'." },
  { id: "t067", question: "They _____ just _____ a new house.", options: ["have/bought", "had/bought", "are/buying", "were/buying"], correctIndex: 0, explanation: "Present Perfect + 'just' (vừa mới): have just + V3." },
  { id: "t068", question: "How long _____ you _____ here?", options: ["do/live", "did/live", "have/lived", "are/living"], correctIndex: 2, explanation: "'How long' hỏi về khoảng thời gian → Present Perfect: Have you lived here?" },
  { id: "t069", question: "She _____ already _____ three chapters.", options: ["has/read", "is/reading", "was/reading", "had/read"], correctIndex: 0, explanation: "Present Perfect + 'already' (đã rồi): has already + V3." },
  { id: "t070", question: "I _____ this book for two weeks now.", options: ["read", "am reading", "have been reading", "was reading"], correctIndex: 2, explanation: "Present Perfect Continuous với 'for + khoảng thời gian' → nhấn mạnh hành động đang diễn ra liên tục." },
  { id: "t071", question: "Before she became famous, she _____ in a small village.", options: ["lives", "lived", "has lived", "had lived"], correctIndex: 3, explanation: "Past Perfect (had lived) cho hành động xảy ra trước một thời điểm quá khứ khác (became famous)." },
  { id: "t072", question: "He _____ the keys when his wife called.", options: ["was losing", "lost", "has lost", "had been losing"], correctIndex: 0, explanation: "Past Continuous (was losing) cho hành động đang diễn ra khi bị gián đoạn bởi cuộc gọi." },
  { id: "t073", question: "I _____ (never) _____ Thai food before I visited Bangkok.", options: ["have/eaten", "had/eaten", "was/eating", "did/eat"], correctIndex: 1, explanation: "Past Perfect + never cho kinh nghiệm chưa có trước một thời điểm trong quá khứ." },
  { id: "t074", question: "By the time the film started, we _____ our popcorn.", options: ["finish", "finished", "have finished", "had finished"], correctIndex: 3, explanation: "Dùng Past Perfect vì hành động ăn hết bắp rang đã xảy ra trước khi phim bắt đầu." },
  { id: "t075", question: "She _____ for hours when she finally found what she was looking for.", options: ["searched", "was searching", "had been searching", "has been searching"], correctIndex: 2, explanation: "Past Perfect Continuous (had been searching) nhấn mạnh hành động liên tục trước một kết quả trong quá khứ." },
  { id: "t076", question: "I think it _____ be a great party tonight.", options: ["is going to", "will", "would", "shall"], correctIndex: 1, explanation: "Dùng 'will' cho dự đoán/ý kiến cá nhân (I think/believe/expect + will)." },
  { id: "t077", question: "Watch out! You _____ drop that vase!", options: ["will", "are going to", "would", "shall"], correctIndex: 1, explanation: "Dùng 'be going to' khi thấy bằng chứng rõ ràng về điều sắp xảy ra ngay lập tức." },
  { id: "t078", question: "I promise I _____ be late again.", options: ["won't", "am not going to", "wouldn't", "don't"], correctIndex: 0, explanation: "Lời hứa trong tương lai → 'will/won't'. Phủ định: won't." },
  { id: "t079", question: "This time next week, we _____ on a beach in Thailand.", options: ["lie", "will lie", "will be lying", "are lying"], correctIndex: 2, explanation: "Future Continuous (will be + V-ing) cho hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai." },
  { id: "t080", question: "By the end of this year, he _____ 10 books.", options: ["writes", "will write", "will have written", "is writing"], correctIndex: 2, explanation: "Future Perfect (will have + V3) cho hành động sẽ hoàn thành trước 'by the end of this year'." },
  { id: "t081", question: "She _____ smoke but she gave it up last year.", options: ["used to", "is used to", "was used to", "got used to"], correctIndex: 0, explanation: "'Used to + V' diễn tả thói quen/trạng thái trong quá khứ không còn nữa." },
  { id: "t082", question: "He _____ walk to school when he was young.", options: ["used to", "is used to", "has used to", "was used to"], correctIndex: 0, explanation: "'Used to + V nguyên thể' = thói quen trong quá khứ đã chấm dứt." },
  { id: "t083", question: "As a child, he _____ spend hours building model trains.", options: ["would", "will", "should", "used to"], correctIndex: 0, explanation: "'Would + V' diễn tả thói quen lặp đi lặp lại trong quá khứ (không dùng cho trạng thái)." },
  { id: "t084", question: "My grandfather _____ tell us stories about his youth.", options: ["would", "will", "could", "should"], correctIndex: 0, explanation: "'Would + V' cho thói quen trong quá khứ (nhớ lại kỷ niệm). Phù hợp hơn 'used to' trong văn kể chuyện." },
  { id: "t085", question: "There _____ be a cinema here, but it was demolished.", options: ["used to", "would", "will", "is going to"], correctIndex: 0, explanation: "'Used to' dùng cho trạng thái trong quá khứ (sự tồn tại). Không dùng 'would' cho trạng thái." },
  { id: "t086", question: "She _____ not use a computer at all before she started this job.", options: ["used to", "could", "would", "did"], correctIndex: 0, explanation: "Phủ định 'used to': didn't use to = used not to. Ở đây là 'used to not' → cấu trúc đúng là 'didn't use to'." },
  { id: "t087", question: "They _____ live in London before moving to Paris.", options: ["used to", "are used to", "get used to", "would"], correctIndex: 0, explanation: "'Used to live' = từng sống (trạng thái), không dùng 'would' cho trạng thái." },
  { id: "t088", question: "She _____ believe in ghosts, but not anymore.", options: ["used to", "would", "was", "has"], correctIndex: 0, explanation: "'Believe' là state verb → dùng 'used to' (không dùng 'would') cho trạng thái quá khứ." },
  { id: "t089", question: "I _____ own a motorbike before I got a car.", options: ["used to", "would", "have", "am"], correctIndex: 0, explanation: "'Own' là state verb → dùng 'used to + V', không dùng 'would'." },
  { id: "t090", question: "She _____ go jogging every morning when she was in college.", options: ["would", "will", "used", "has used to"], correctIndex: 0, explanation: "'Would + V' cho thói quen lặp đi lặp lại trong quá khứ (hành động, không phải trạng thái)." },
  { id: "t091", question: "I _____ think you were right, but I've changed my mind.", options: ["used to", "would", "was", "have"], correctIndex: 0, explanation: "'Think' là state verb → dùng 'used to', không dùng 'would'." },
  { id: "t092", question: "Careful — you _____ fall if you lean too far!", options: ["will", "are going to", "would", "shall"], correctIndex: 0, explanation: "Dùng 'will' cho cảnh báo về kết quả có thể xảy ra (điều kiện hiện tại)." },
  { id: "t093", question: "I don't think she _____ come to the meeting.", options: ["will", "is going to", "would", "shall"], correctIndex: 0, explanation: "Dự đoán với 'I don't think' → dùng 'will'." },
  { id: "t094", question: "The bus _____ at noon — don't miss it!", options: ["will leave", "is going to leave", "leaves", "left"], correctIndex: 2, explanation: "Lịch trình cố định (cố định theo thời khóa biểu) → Present Simple." },
  { id: "t095", question: "She _____ meet the director at 2 PM tomorrow. (It's in her diary)", options: ["will meet", "is meeting", "meets", "would meet"], correctIndex: 1, explanation: "Present Continuous cho cuộc hẹn đã được lên lịch cụ thể trong tương lai." },
  { id: "t096", question: "By the time you read this, I _____ for France.", options: ["leave", "am leaving", "will have left", "will leave"], correctIndex: 2, explanation: "Future Perfect (will have left) cho hành động sẽ hoàn thành trước thời điểm 'By the time you read this'." },
  { id: "t097", question: "Next month at this time, she _____ for her finals.", options: ["studies", "will study", "will be studying", "has studied"], correctIndex: 2, explanation: "Future Continuous (will be studying) cho hành động sẽ đang xảy ra tại thời điểm cụ thể trong tương lai." },
  { id: "t098", question: "I _____ my sister since last Christmas — I miss her.", options: ["don't see", "didn't see", "haven't seen", "won't see"], correctIndex: 2, explanation: "Present Perfect với 'since' cho trạng thái kéo dài từ quá khứ đến hiện tại." },
  { id: "t099", question: "He _____ in three different countries before he was 30.", options: ["lived", "was living", "has lived", "had lived"], correctIndex: 3, explanation: "Past Perfect (had lived) cho kinh nghiệm tích lũy trước một mốc thời gian quá khứ (before he was 30)." },
  { id: "t100", question: "She was cooking when I _____ home.", options: ["come", "came", "was coming", "had come"], correctIndex: 1, explanation: "Past Simple (came) cho hành động ngắn gián đoạn hành động dài đang xảy ra (Past Continuous: was cooking)." },
  { id: "t101", question: "My grandmother _____ five languages fluently.", options: ["speaks", "is speaking", "has spoken", "spoke"], correctIndex: 0, explanation: "Khả năng hiện tại (sự thật) → Present Simple. 'Speak' + 5 languages." },
  { id: "t102", question: "We _____ live here for long — we're moving next month.", options: ["don't", "aren't going to", "won't", "haven't"], correctIndex: 1, explanation: "Kế hoạch đã quyết định trong tương lai → 'be going to' hoặc Present Continuous. 'Aren't going to' phù hợp nhất ở đây." },
  { id: "t103", question: "He _____ (already) _____ his car twice this month.", options: ["had/repaired", "has/repaired", "is/repairing", "was/repairing"], correctIndex: 1, explanation: "Present Perfect + 'already' + 'this month' (khoảng thời gian chưa kết thúc) → has already repaired." },
  { id: "t104", question: "She _____ TV when I phoned her.", options: ["watches", "watched", "was watching", "has watched"], correctIndex: 2, explanation: "Past Continuous (was watching) cho hành động đang diễn ra khi tôi gọi điện." },
  { id: "t105", question: "When _____ you last _____ abroad?", options: ["do/go", "did/go", "have/gone", "were/going"], correctIndex: 1, explanation: "Câu hỏi Past Simple: When did you last go...? (hỏi về thời điểm cụ thể trong quá khứ)" },
  { id: "t106", question: "They _____ for 6 hours before they finally stopped to rest.", options: ["drove", "were driving", "had been driving", "have been driving"], correctIndex: 2, explanation: "Past Perfect Continuous (had been driving) nhấn mạnh hành động kéo dài liên tục trước khi dừng lại." },
  { id: "t107", question: "I _____ believe what just happened!", options: ["can't", "couldn't", "don't", "won't"], correctIndex: 0, explanation: "'Can't believe' là diễn đạt tự nhiên cho sự ngạc nhiên ở thời điểm hiện tại." },
  { id: "t108", question: "The company _____ a new product line next quarter.", options: ["launches", "has launched", "is launching", "launched"], correctIndex: 2, explanation: "Present Continuous cho kế hoạch được sắp xếp sẵn trong tương lai gần." },
  { id: "t109", question: "I _____ you that was a bad idea!", options: ["tell", "told", "was telling", "have told"], correctIndex: 1, explanation: "Past Simple (told) cho sự kiện đã xảy ra trong quá khứ. 'I told you so!' là cụm thông dụng." },
  { id: "t110", question: "She _____ for the job interview all week.", options: ["prepares", "has been preparing", "prepared", "is preparing"], correctIndex: 1, explanation: "Present Perfect Continuous với 'all week' → hành động liên tục trong khoảng thời gian dẫn đến hiện tại." },
  { id: "t111", question: "The accident _____ while workers were repairing the bridge.", options: ["happens", "happened", "was happening", "has happened"], correctIndex: 1, explanation: "Past Simple (happened) cho sự kiện xảy ra tại một thời điểm cụ thể trong khi (while) có hành động khác đang diễn ra." },
  { id: "t112", question: "I _____ this song since I was a teenager.", options: ["love", "loved", "have loved", "am loving"], correctIndex: 2, explanation: "Present Perfect với 'since' cho trạng thái kéo dài từ quá khứ. 'Love' là state verb nhưng có thể dùng perfect tense." },
  { id: "t113", question: "He _____ chess — he finds it too complicated.", options: ["doesn't like", "isn't liking", "hasn't liked", "didn't like"], correctIndex: 0, explanation: "'Like' là state verb → Present Simple phủ định: doesn't like." },
  { id: "t114", question: "She _____ five emails by the time the meeting ended.", options: ["writes", "wrote", "has written", "had written"], correctIndex: 3, explanation: "Past Perfect (had written) cho hành động hoàn thành trước thời điểm quá khứ khác (when the meeting ended)." },
  { id: "t115", question: "I _____ my aunt next Tuesday — can you join us?", options: ["will visit", "am visiting", "visited", "visit"], correctIndex: 1, explanation: "Present Continuous (am visiting) cho cuộc hẹn đã được lên kế hoạch cụ thể." },
  { id: "t116", question: "By next January, they _____ married for 25 years.", options: ["are", "will be", "will have been", "have been"], correctIndex: 2, explanation: "Future Perfect (will have been) cho trạng thái sẽ kéo dài đến một điểm trong tương lai." },
  { id: "t117", question: "She _____ seem very happy today, does she?", options: ["doesn't", "isn't", "hasn't", "won't"], correctIndex: 0, explanation: "'Seem' là state verb → Present Simple: She doesn't seem..." },
  { id: "t118", question: "He _____ contain milk — you should check the label if you're lactose intolerant.", options: ["might", "may", "could", "appears to"], correctIndex: 1, explanation: "'May contain' = có thể chứa (nhãn sản phẩm). Dùng 'may' cho khả năng." },
  { id: "t119", question: "I _____ own a car when I was in my twenties.", options: ["used to", "would", "did used to", "was used to"], correctIndex: 0, explanation: "'Used to + V' cho trạng thái trong quá khứ. 'Own' là state verb nên không dùng 'would'." },
  { id: "t120", question: "My parents _____ argue a lot, but they are much calmer now.", options: ["used to", "would", "are used to", "will"], correctIndex: 0, explanation: "'Used to' cho thói quen/trạng thái trong quá khứ không còn xảy ra nữa." },
  { id: "t121", question: "She _____ her presentation when the fire alarm went off.", options: ["gives", "gave", "was giving", "had given"], correctIndex: 2, explanation: "Past Continuous (was giving) cho hành động đang diễn ra khi bị gián đoạn." },
  { id: "t122", question: "Do you know what _____ in 1215?", options: ["happened", "has happened", "was happening", "had happened"], correctIndex: 0, explanation: "Sự kiện lịch sử với thời điểm cụ thể (1215) → Past Simple." },
  { id: "t123", question: "She _____ want anything to eat — she's not hungry.", options: ["doesn't", "isn't", "won't", "hasn't"], correctIndex: 0, explanation: "'Want' là state verb → Present Simple phủ định: doesn't want." },
  { id: "t124", question: "I _____ you a hand with those bags.", options: ["give", "am giving", "will give", "'ll give"], correctIndex: 3, explanation: "Đề nghị tức thì (quyết định tại thời điểm nói) → 'll give (= will give)." },
  { id: "t125", question: "She was tired because she _____ all the way from the station.", options: ["runs", "ran", "has run", "had been running"], correctIndex: 3, explanation: "Past Perfect Continuous (had been running) giải thích nguyên nhân cho trạng thái quá khứ (was tired)." },
  { id: "t126", question: "I _____ understand why she reacted like that.", options: ["don't", "didn't", "can't", "couldn't"], correctIndex: 1, explanation: "Diễn tả tình trạng không hiểu tại một thời điểm quá khứ → Past Simple: didn't understand." },
  { id: "t127", question: "The match _____ when I turned on the TV.", options: ["ends", "ended", "had already ended", "is ending"], correctIndex: 2, explanation: "Past Perfect (had already ended) cho hành động đã hoàn thành trước khi tôi bật TV." },
  { id: "t128", question: "How many times _____ you _____ this film?", options: ["do/see", "did/see", "have/seen", "are/seeing"], correctIndex: 2, explanation: "Câu hỏi về số lần kinh nghiệm → Present Perfect: How many times have you seen...?" },
  { id: "t129", question: "She _____ (already) _____ when I arrived.", options: ["has/left", "had/left", "was/leaving", "is/leaving"], correctIndex: 1, explanation: "Past Perfect (had already left) cho hành động hoàn thành trước khi tôi đến." },
  { id: "t130", question: "I _____ hear what you're saying — can you speak up?", options: ["don't", "can't", "won't", "am not"], correctIndex: 1, explanation: "'Can't hear' diễn tả khả năng hiện tại (không nghe được). Không dùng 'don't hear'." },
  { id: "t131", question: "She _____ here for three years before she was promoted.", options: ["works", "worked", "was working", "had been working"], correctIndex: 3, explanation: "Past Perfect Continuous (had been working) cho hành động liên tục trước sự kiện quá khứ (was promoted)." },
  { id: "t132", question: "We _____ have dinner at 7 PM every Friday. (routine)", options: ["have", "are having", "will have", "had"], correctIndex: 0, explanation: "Thói quen thường xuyên → Present Simple (have). 'Every Friday' là dấu hiệu nhận biết." },
  { id: "t133", question: "She _____ live in London — I used to see her on the Tube.", options: ["used to", "is used to", "would", "was"], correctIndex: 0, explanation: "'Used to live' → trạng thái trong quá khứ (từng sống). 'Would' không dùng cho trạng thái." },
  { id: "t134", question: "He _____ buy flowers for his wife every week. (past habit)", options: ["used to", "would", "was", "could"], correctIndex: 1, explanation: "'Would + V' cho thói quen lặp lại trong quá khứ. Cả 'used to' và 'would' đều đúng, nhưng 'would' phổ biến hơn trong ngữ cảnh kể chuyện." },
  { id: "t135", question: "I _____ you tomorrow as soon as I have the results.", options: ["call", "am calling", "will call", "called"], correctIndex: 2, explanation: "'Will' cho lời hứa tương lai. Mệnh đề 'as soon as' + Present Simple." },
  { id: "t136", question: "Look — the children _____ in the garden.", options: ["play", "plays", "are playing", "played"], correctIndex: 2, explanation: "'Look' là tín hiệu dùng Present Continuous → đang diễn ra ngay lúc này." },
  { id: "t137", question: "She _____ know that I'm waiting for her.", options: ["doesn't", "isn't", "won't", "can't"], correctIndex: 0, explanation: "'Know' là state verb → Present Simple phủ định: doesn't know." },
  { id: "t138", question: "I _____ this problem yet — give me more time.", options: ["don't solve", "didn't solve", "haven't solved", "am not solving"], correctIndex: 2, explanation: "Present Perfect phủ định với 'yet' → haven't solved yet." },
  { id: "t139", question: "He _____ English for five years when he moved to the UK.", options: ["learns", "learned", "has learned", "had been learning"], correctIndex: 3, explanation: "Past Perfect Continuous (had been learning) cho hành động liên tục trước sự kiện quá khứ (moved to the UK)." },
  { id: "t140", question: "They _____ to the cinema last weekend.", options: ["go", "goes", "went", "have gone"], correctIndex: 2, explanation: "'Last weekend' = thời điểm cụ thể trong quá khứ → Past Simple (went)." },
  { id: "t141", question: "She _____ believe in Santa Claus when she was little.", options: ["used to", "is used to", "gets used to", "was used to"], correctIndex: 0, explanation: "'Believe' là state verb → 'used to believe' (trạng thái trong quá khứ)." },
  { id: "t142", question: "At this time next year, I _____ at university.", options: ["study", "will study", "will be studying", "am studying"], correctIndex: 2, explanation: "Future Continuous (will be studying) cho hành động đang diễn ra tại thời điểm trong tương lai." },
  { id: "t143", question: "She _____ (just) _____ the news — she looks shocked.", options: ["heard/has", "has/heard", "had/heard", "is/hearing"], correctIndex: 1, explanation: "Present Perfect + 'just' (vừa mới): has just + V3. 'She looks shocked' = kết quả hiện tại." },
  { id: "t144", question: "They _____ the car when I passed by the garage.", options: ["fix", "fixed", "were fixing", "had fixed"], correctIndex: 2, explanation: "Past Continuous (were fixing) cho hành động đang diễn ra khi tôi đi qua." },
  { id: "t145", question: "I _____ this word in the dictionary three times but I still forget it.", options: ["look up", "have looked up", "looked up", "had looked up"], correctIndex: 1, explanation: "Present Perfect + 'three times' (số lần kinh nghiệm) → have looked up." },
  { id: "t146", question: "She _____ work until 3 AM every night during the project.", options: ["would", "will", "could", "should"], correctIndex: 0, explanation: "'Would + V' cho thói quen lặp lại trong quá khứ ('during the project' cho thấy đây là quá khứ)." },
  { id: "t147", question: "He _____ the presentation by the time the boss arrives.", options: ["finishes", "will finish", "will have finished", "finished"], correctIndex: 2, explanation: "Future Perfect (will have finished) cho hành động hoàn thành trước thời điểm 'by the time the boss arrives'." },
  { id: "t148", question: "I _____ think that was a good idea at the time.", options: ["used to", "would", "was", "did"], correctIndex: 0, explanation: "'Think' là state verb → 'used to think' (không dùng 'would think')." },
  { id: "t149", question: "She _____ (not) _____ yet — let's wait a bit longer.", options: ["has/arrived", "is/arriving", "was/arriving", "had/arrived"], correctIndex: 0, explanation: "Present Perfect phủ định với 'yet': has not arrived yet." },
  { id: "t150", question: "By the end of the week, we _____ all our savings.", options: ["spend", "spent", "will have spent", "will spend"], correctIndex: 2, explanation: "Future Perfect (will have spent) cho hành động hoàn thành trước cuối tuần." },
  { id: "t151", question: "The teacher _____ always _____ everything twice. (good habit)", options: ["is/explaining", "explains/explain", "does/explain", "explained/explains"], correctIndex: 0, explanation: "Present Continuous + always cho thói quen đặc trưng (ở đây là tích cực)." },
  { id: "t152", question: "She _____ her keys again — that's the third time this week!", options: ["loses", "lost", "is losing", "has lost"], correctIndex: 3, explanation: "Present Perfect (has lost) → hành động vừa xảy ra có kết quả liên quan đến hiện tại (third time this week)." },
  { id: "t153", question: "They _____ their homework before dinner every day.", options: ["do", "are doing", "have done", "did"], correctIndex: 0, explanation: "Thói quen hàng ngày → Present Simple (do). 'Every day' là dấu hiệu." },
  { id: "t154", question: "The project _____ by the end of this month, I promise.", options: ["completes", "will complete", "will be completed", "is completing"], correctIndex: 2, explanation: "Câu bị động tương lai: will be completed. Đây là kết quả cần đạt được." },
  { id: "t155", question: "He _____ work here — he transferred to another department.", options: ["doesn't", "didn't use to", "no longer", "used to not"], correctIndex: 1, explanation: "Phủ định của 'used to': didn't use to (= no longer) diễn tả trạng thái không còn đúng nữa." },
  { id: "t156", question: "I _____ know what to do — I'm completely lost!", options: ["don't", "am not", "haven't", "didn't"], correctIndex: 0, explanation: "'Know' là state verb → Present Simple phủ định: don't know." },
  { id: "t157", question: "The match _____ at 3 PM. Don't be late.", options: ["starts", "will start", "is going to start", "is starting"], correctIndex: 0, explanation: "Lịch trình cố định → Present Simple. Đây là thông tin từ lịch thi đấu." },
  { id: "t158", question: "She _____ write to her friends every week when she lived abroad.", options: ["used to", "would", "will", "has"], correctIndex: 1, explanation: "'Would + V' cho thói quen lặp lại trong quá khứ. Cả 'used to' đều đúng nhưng 'would' tự nhiên hơn ở đây." },
  { id: "t159", question: "I _____ the doctor tomorrow at 10 AM.", options: ["see", "am seeing", "will see", "have seen"], correctIndex: 1, explanation: "Present Continuous (am seeing) cho cuộc hẹn cụ thể đã được sắp xếp trong tương lai." },
  { id: "t160", question: "He _____ already _____ two novels before he turned 25.", options: ["wrote/has", "had/written", "has/written", "was/writing"], correctIndex: 1, explanation: "Past Perfect (had already written) cho thành tích hoàn thành trước một mốc thời gian quá khứ." },
  { id: "t161", question: "I _____ a headache — do you have any paracetamol?", options: ["have", "am having", "had", "have had"], correctIndex: 0, explanation: "'Have' là state verb trong nghĩa sở hữu/cảm giác → Present Simple: I have a headache." },
  { id: "t162", question: "She _____ a great time at the party — she's still smiling!", options: ["had", "has", "is having", "has had"], correctIndex: 3, explanation: "Present Perfect (has had) → kinh nghiệm vừa qua, kết quả vẫn thấy ở hiện tại (still smiling)." },
  { id: "t163", question: "When I was young, my family _____ live in the countryside.", options: ["used to", "would", "did used to", "was used to"], correctIndex: 0, explanation: "'Live' diễn tả trạng thái (state) → dùng 'used to live', không dùng 'would live'." },
  { id: "t164", question: "They _____ for 20 minutes now, and there's no sign of an agreement.", options: ["argue", "argued", "are arguing", "have been arguing"], correctIndex: 3, explanation: "Present Perfect Continuous (have been arguing) + 'for 20 minutes now' → hành động liên tục đang diễn ra." },
  { id: "t165", question: "She _____ meet him at the airport if he tells her what time his flight lands.", options: ["will", "would", "is going to", "shall"], correctIndex: 0, explanation: "Câu điều kiện loại 1: if + Present Simple → will + V." },
  { id: "t166", question: "He _____ in this town all his life.", options: ["lives", "lived", "has lived", "is living"], correctIndex: 2, explanation: "Present Perfect (has lived) cho hành động/trạng thái kéo dài từ quá khứ đến hiện tại ('all his life')." },
  { id: "t167", question: "She _____ her best friend since they had a big argument.", options: ["doesn't see", "didn't see", "hasn't seen", "won't see"], correctIndex: 2, explanation: "Present Perfect phủ định với 'since' → hasn't seen (trạng thái từ quá khứ đến hiện tại)." },
  { id: "t168", question: "I need to hurry — the flight _____ in an hour!", options: ["leaves", "is leaving", "will leave", "left"], correctIndex: 1, explanation: "Present Continuous (is leaving) cho kế hoạch cụ thể sắp xảy ra, nhấn mạnh tính cấp bách." },
  { id: "t169", question: "The scientist _____ on this research for over a decade.", options: ["works", "worked", "has been working", "is working"], correctIndex: 2, explanation: "Present Perfect Continuous (has been working) nhấn mạnh quá trình liên tục từ quá khứ đến hiện tại." },
  { id: "t170", question: "They _____ married for 30 years next June.", options: ["will be", "are", "have been", "will have been"], correctIndex: 3, explanation: "Future Perfect (will have been married) cho trạng thái sẽ kéo dài đến điểm cụ thể trong tương lai." },
  { id: "t171", question: "I _____ believe she actually won the competition!", options: ["can't", "don't", "won't", "haven't"], correctIndex: 0, explanation: "'Can't believe' diễn tả sự ngạc nhiên mạnh ở thời điểm hiện tại. Phổ biến hơn 'don't believe' trong ngữ cảnh này." },
  { id: "t172", question: "He _____ (already) _____ when the ambulance arrived.", options: ["died/has", "has/died", "had/died", "was/dying"], correctIndex: 2, explanation: "Past Perfect (had already died) cho hành động hoàn thành trước sự kiện quá khứ khác (the ambulance arrived)." },
  { id: "t173", question: "She _____ her driving test four times so far.", options: ["fails", "failed", "has failed", "had failed"], correctIndex: 2, explanation: "Present Perfect với 'so far' (cho đến nay) → hành động lặp lại trong khoảng thời gian chưa kết thúc." },
  { id: "t174", question: "This time last year, we _____ on holiday in Spain.", options: ["are", "were", "have been", "will be"], correctIndex: 1, explanation: "'This time last year' chỉ một thời điểm cụ thể trong quá khứ → Past Simple (were)." },
  { id: "t175", question: "They _____ the project for months before they finally gave up.", options: ["work", "worked", "had been working", "were working"], correctIndex: 2, explanation: "Past Perfect Continuous (had been working) nhấn mạnh hành động kéo dài liên tục trước kết quả quá khứ." },
  { id: "t176", question: "I _____ sure she's the right person for the job.", options: ["am", "was", "have been", "will be"], correctIndex: 0, explanation: "'Sure' diễn tả ý kiến/trạng thái hiện tại → Present Simple: I am sure." },
  { id: "t177", question: "She _____ the violin since she was six.", options: ["plays", "played", "has been playing", "is playing"], correctIndex: 2, explanation: "Present Perfect Continuous (has been playing) với 'since' nhấn mạnh quá trình liên tục." },
  { id: "t178", question: "I _____ want to disturb you, but this is urgent.", options: ["don't", "am not", "won't", "haven't"], correctIndex: 0, explanation: "'Want' là state verb → Present Simple phủ định: don't want." },
  { id: "t179", question: "She _____ (never) _____ such a beautiful sunset before.", options: ["sees/has", "had/seen", "saw/never", "has/seen"], correctIndex: 3, explanation: "Present Perfect (has never seen) cho kinh nghiệm chưa từng có: has never seen such..." },
  { id: "t180", question: "He _____ tired when he got off the plane after a 15-hour flight.", options: ["is", "was", "has been", "had been"], correctIndex: 1, explanation: "Past Simple (was tired) diễn tả trạng thái tại thời điểm cụ thể trong quá khứ." },
  { id: "t181", question: "By the time the police arrived, the thief _____.", options: ["escapes", "escaped", "had escaped", "was escaping"], correctIndex: 2, explanation: "Past Perfect (had escaped) cho hành động hoàn thành trước sự kiện quá khứ khác (police arrived)." },
  { id: "t182", question: "I _____ agree with him on that point.", options: ["don't", "am not", "won't", "haven't"], correctIndex: 0, explanation: "'Agree' là state verb → Present Simple phủ định: don't agree." },
  { id: "t183", question: "She _____ still _____ for the results of the exam.", options: ["is/waiting", "has/waited", "was/waiting", "will/wait"], correctIndex: 0, explanation: "Present Continuous (is still waiting) → hành động đang tiếp tục ngay lúc này." },
  { id: "t184", question: "They _____ in this house since 1995.", options: ["live", "lived", "are living", "have been living"], correctIndex: 3, explanation: "Present Perfect Continuous (have been living) với 'since' nhấn mạnh hành động liên tục từ 1995 đến nay." },
  { id: "t185", question: "He _____ (just) _____ a shower — his hair is still wet.", options: ["took/had", "had/taken", "has/taken", "is/taking"], correctIndex: 2, explanation: "Present Perfect + 'just': has just taken → kết quả hiện tại (hair is still wet)." },
  { id: "t186", question: "My sister _____ always _____ my stuff without asking! (irritating)", options: ["is/borrowing", "has/borrowed", "was/borrowing", "did/borrow"], correctIndex: 0, explanation: "Present Continuous + always → thói quen gây khó chịu: is always borrowing." },
  { id: "t187", question: "I _____ the meeting tomorrow, I promise.", options: ["attend", "attended", "will attend", "am attending"], correctIndex: 2, explanation: "Lời hứa tự phát về tương lai → 'will + V'." },
  { id: "t188", question: "She _____ (not) _____ anything since this morning.", options: ["has/eaten", "is/eating", "was/eating", "had/eaten"], correctIndex: 0, explanation: "Present Perfect phủ định (has not eaten) với 'since this morning' → trạng thái từ sáng đến giờ." },
  { id: "t189", question: "When I was a child, I _____ be afraid of dogs.", options: ["used to", "would", "was", "am"], correctIndex: 0, explanation: "'Afraid of' là trạng thái → 'used to be afraid of' (không dùng 'would be afraid')." },
  { id: "t190", question: "By the end of today, I _____ 50 pages of this report.", options: ["write", "will write", "will have written", "am writing"], correctIndex: 2, explanation: "Future Perfect (will have written) cho mục tiêu sẽ hoàn thành trước 'the end of today'." },
  { id: "t191", question: "She _____ know whether to laugh or cry.", options: ["doesn't", "isn't", "won't", "can't"], correctIndex: 0, explanation: "'Know' là state verb → Present Simple phủ định: doesn't know." },
  { id: "t192", question: "They _____ just _____ their first anniversary.", options: ["celebrated/have", "have/celebrated", "had/celebrated", "are/celebrating"], correctIndex: 1, explanation: "Present Perfect + 'just': have just celebrated → sự kiện vừa mới xảy ra." },
  { id: "t193", question: "She _____ in the library when her phone suddenly rang.", options: ["studies", "studied", "was studying", "had studied"], correctIndex: 2, explanation: "Past Continuous (was studying) cho hành động đang diễn ra khi bị gián đoạn (phone rang)." },
  { id: "t194", question: "He _____ (never) _____ a lie in his life. (He's very honest)", options: ["has/told", "told/never", "is/telling", "had/told"], correctIndex: 0, explanation: "Present Perfect + never cho kinh nghiệm chưa từng xảy ra trong suốt cuộc đời." },
  { id: "t195", question: "I _____ seem to remember where I put my glasses.", options: ["don't", "can't", "won't", "am not"], correctIndex: 0, explanation: "'Seem' là state verb → Present Simple: I don't seem to remember..." },
  { id: "t196", question: "The sun _____ by the time we reach the top of the mountain.", options: ["sets", "will set", "will have set", "is setting"], correctIndex: 2, explanation: "Future Perfect (will have set) → hành động sẽ hoàn thành trước thời điểm 'we reach the top'." },
  { id: "t197", question: "She _____ appear very confident in interviews.", options: ["doesn't", "isn't", "won't", "hasn't"], correctIndex: 0, explanation: "'Appear' dùng như state verb ở đây → Present Simple: doesn't appear." },
  { id: "t198", question: "I _____ see what you mean — could you explain it differently?", options: ["don't", "can't", "am not", "won't"], correctIndex: 1, explanation: "'Can't see' (không thể hiểu/nhìn thấy) diễn tả khả năng → Modal: can't." },
  { id: "t199", question: "They _____ for over an hour by the time the last guest arrives.", options: ["wait", "will wait", "will have been waiting", "have been waiting"], correctIndex: 2, explanation: "Future Perfect Continuous (will have been waiting) nhấn mạnh hành động liên tục hoàn thành trước thời điểm tương lai." },
  { id: "t200", question: "She _____ English before, so the course was easy for her.", options: ["studies", "studied", "has studied", "had studied"], correctIndex: 3, explanation: "Past Perfect (had studied) → kinh nghiệm có được trước thời điểm quá khứ khác (the course was easy)." },
];
